insert into project_cost_models (cost_model_id, project_id, title, case_kind, case_label, version_label, status, source_url, source_note, summary_md, visibility, system_scope_md, target_total_cost_per_m3, target_margin_rate, target_note, unit_basis_label) values ('cm_p21_fuel_260914', 'p21', 'SX コスト試算（燃料）', 'biodiesel', 'バイオディーゼル（FAME・船舶向け）', '260914版', 'active', null, '260818 バイオ燃料アップサイド検討資料／260903 事業概要／260907 シアノ→FAME→SAF 工程とマテバラ推定／排水処理のコスト試算 260914版の培養設備', 'SXのシアノバクテリアで**バイオディーゼル（FAME・船舶向け）**を作って売る事業を、燃料1Lあたりの総コストで試算する。ゴールツリーの「バイオディーゼル事業は成立するか」に数字で答えるためのシート。
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_business_annual_volume', 'cm_p21_fuel_260914', null, '事業の規模と売価', '年間の燃料の量（事業全体）', 50000000, null, 'L/年', 'C', '仮置き', 'AMD（内部）', true, 'business_annual_volume', '排水処理のコスト試算と同じく、IPOできる大量生産の状態として売上100億円に届く量で置いた（売上100億円 ÷ 想定売価200円/L ＝ 5,000万L/年）。260818 バイオ燃料アップサイド検討資料の売上シナリオは、2033年度 80億円（4,000万L/年）、2035年度 400億円（2億L/年）。年に要る菌体の量と、培養設備・燃料化設備の系列数は、この量から計算する（入力ではない）。売価を変えると売上も変わるので、売上100億円に合わせるときはこの量も変える。', 'amd_internal', 100, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_sale_price', 'cm_p21_fuel_260914', null, '事業の規模と売価', '想定売価（船舶向けFAME）', 200, null, '円/L', 'C', '資料記載', 'AMD（内部）', true, 'sale_price', '260818 バイオ燃料アップサイド検討資料・260903 事業概要の仮置き。市場参照は、米国DOEの2025年10月のB99/B100小売平均 4.30ドル/ガロン（1ドル161円で約183円/L）。日本の船舶向けの販売条件（混合率・引き渡し場所・物流・品質契約・税）で置き換える。', 'amd_internal', 101, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_fame_potential', 'cm_p21_fuel_260914', null, '菌体から取れる燃料（収率）', '全菌体のFAMEポテンシャル（基準）', 10, null, '%', 'H', '仮置き', '杉浦先生（外部分析）', true, 'fame_potential', '乾燥菌体を分析したときに得られるFAME（脂肪酸メチルエステル。バイオディーゼルの成分）の重さの割合。メタノールから加わるメチル基を含む分析上の量。2026-09-07 の工程とマテバラ推定の設計仮定で、SX株では測っていない。天然のシアノバクテリアは5〜12%程度が一般的とされる。シアノバクテリアの油は膜の糖脂質・リン脂質が中心なので、抽出した油の量（20%など）をそのままFAMEの量に置き換えない。燃料1Lに要る菌体の量にそのまま効く、いちばん大きい感度。', 'amd_internal', 110, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_fame_potential_low', 'cm_p21_fuel_260914', null, '菌体から取れる燃料（収率）', '全菌体のFAMEポテンシャル（低位）', 5, null, '%', 'H', '仮置き', '杉浦先生（外部分析）', false, 'fame_potential_low', '2026-09-07 の工程とマテバラ推定の低位の仮定。', 'amd_internal', 111, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_fame_potential_high', 'cm_p21_fuel_260914', null, '菌体から取れる燃料（収率）', '全菌体のFAMEポテンシャル（改善）', 20, null, '%', 'H', '仮置き', '杉浦先生（外部分析）', false, 'fame_potential_high', '2026-09-07 の工程とマテバラ推定の改善の仮定。統計的な上限や将来予測ではない。', 'amd_internal', 112, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_harvest_recovery', 'cm_p21_fuel_260914', null, '菌体から取れる燃料（収率）', '菌体回収率（基準）', 95, null, '%', 'H', '仮置き', '中島先生', false, 'harvest_recovery', '培養液から濃縮・脱水で取り出せる菌体の割合。取り出せなかった菌体は培養へ戻す液と一緒に抜ける。2026-09-07 の工程とマテバラ推定の設計仮定。', 'amd_internal', 120, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_harvest_recovery_low', 'cm_p21_fuel_260914', null, '菌体から取れる燃料（収率）', '菌体回収率（低位）', 90, null, '%', 'H', '仮置き', '中島先生', false, 'harvest_recovery_low', '2026-09-07 の工程とマテバラ推定の低位の仮定。', 'amd_internal', 121, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_harvest_recovery_high', 'cm_p21_fuel_260914', null, '菌体から取れる燃料（収率）', '菌体回収率（改善）', 98, null, '%', 'H', '仮置き', '中島先生', false, 'harvest_recovery_high', '2026-09-07 の工程とマテバラ推定の改善の仮定。統計的な上限や将来予測ではない。', 'amd_internal', 122, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_extraction_recovery', 'cm_p21_fuel_260914', null, '菌体から取れる燃料（収率）', '脂質抽出回収率（基準）', 90, null, '%', 'H', '仮置き', '中島先生', false, 'extraction_recovery', '固形分20%の湿った菌体から、細胞を壊して溶媒で取り出せる脂質の割合（分析上のFAMEポテンシャルに対して）。菌体を全部乾かす方法は、水を飛ばす熱が燃料の発熱量を大きく超えるので採らない。湿式で90%取れるかは検証課題。', 'amd_internal', 130, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_extraction_recovery_low', 'cm_p21_fuel_260914', null, '菌体から取れる燃料（収率）', '脂質抽出回収率（低位）', 80, null, '%', 'H', '仮置き', '中島先生', false, 'extraction_recovery_low', '2026-09-07 の工程とマテバラ推定の低位の仮定。', 'amd_internal', 131, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_extraction_recovery_high', 'cm_p21_fuel_260914', null, '菌体から取れる燃料（収率）', '脂質抽出回収率（改善）', 95, null, '%', 'H', '仮置き', '中島先生', false, 'extraction_recovery_high', '2026-09-07 の工程とマテバラ推定の改善の仮定。統計的な上限や将来予測ではない。', 'amd_internal', 132, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_methylation_rate', 'cm_p21_fuel_260914', null, '菌体から取れる燃料（収率）', 'メチル化反応率（基準）', 97, null, '%', 'C', '仮置き', '精製事業者', false, 'methylation_rate', '取り出した脂質をメタノールと酸触媒でFAMEに変える割合。水分・遊離脂肪酸・膜脂質が多い原料なので、酸触媒で置いた。', 'amd_internal', 140, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_methylation_rate_low', 'cm_p21_fuel_260914', null, '菌体から取れる燃料（収率）', 'メチル化反応率（低位）', 95, null, '%', 'C', '仮置き', '精製事業者', false, 'methylation_rate_low', '2026-09-07 の工程とマテバラ推定の低位の仮定。', 'amd_internal', 141, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_methylation_rate_high', 'cm_p21_fuel_260914', null, '菌体から取れる燃料（収率）', 'メチル化反応率（改善）', 99, null, '%', 'C', '仮置き', '精製事業者', false, 'methylation_rate_high', '2026-09-07 の工程とマテバラ推定の改善の仮定。統計的な上限や将来予測ではない。', 'amd_internal', 142, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_purification_recovery', 'cm_p21_fuel_260914', null, '菌体から取れる燃料（収率）', 'FAME精製回収率（基準）', 98, null, '%', 'C', '仮置き', '精製事業者', false, 'purification_recovery', '中和・メタノール回収・洗浄・吸着・脱水で、製品として残るFAMEの割合。', 'amd_internal', 150, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_purification_recovery_low', 'cm_p21_fuel_260914', null, '菌体から取れる燃料（収率）', 'FAME精製回収率（低位）', 95, null, '%', 'C', '仮置き', '精製事業者', false, 'purification_recovery_low', '2026-09-07 の工程とマテバラ推定の低位の仮定。', 'amd_internal', 151, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_purification_recovery_high', 'cm_p21_fuel_260914', null, '菌体から取れる燃料（収率）', 'FAME精製回収率（改善）', 99, null, '%', 'C', '仮置き', '精製事業者', false, 'purification_recovery_high', '2026-09-07 の工程とマテバラ推定の改善の仮定。統計的な上限や将来予測ではない。', 'amd_internal', 152, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_fame_density', 'cm_p21_fuel_260914', null, '菌体から取れる燃料（収率）', '燃料（FAME）の密度', 0.88, null, 'kg/L', 'B', '資料記載', 'AMD（内部）', false, 'fame_density', '重さ（kg）から量（L）へ換える値。260818 バイオ燃料アップサイド検討資料・2026-09-07 の工程とマテバラ推定と同じ。', 'amd_internal', 170, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_biomass_cost_override', 'cm_p21_fuel_260914', null, '菌体の原価', '菌体の原価（上書き）', null, null, '円/kg-DCW', 'H', '仮置き', null, true, 'biomass_cost_per_kg_override', '空欄なら培養設備の明細と作業から計算する。値を入れると、その原価で燃料1Lあたりの総コストを計算する。0を入れると、培養の費用を燃料側で持たない形（排水処理向けに作った菌体の余りを使う形など）の総コストが見られる。ただし余りで作れる燃料の量は、排水処理側で余る菌体の量までで、年間の燃料の量の前提とは別に確かめる。', 'amd_internal', 180, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_culture_line_capacity', 'cm_p21_fuel_260914', null, '培養設備（菌体をつくる）', '培養設備1系列の年間生産能力', 33333, null, 'kg-DCW/年', 'H', '推定', '杉浦先生', true, 'culture_line_capacity_kg_year', '排水処理のコスト試算（260914版）と同じ値。培養設備1系列（明細の設備一式）で年に作れる乾燥菌体の量。年に要る菌体の量 ÷ この量 の数だけ系列を並べ、設備の初期投資・年ごとの品質確認・培養の運転を系列の数だけ増やす。明細の設備でこの量を作れるかは確かめていない。燃料の量では系列が1万を超えるので、量産の培養設備の単位（1系列の大きさ）も確かめる。', 'amd_internal', 200, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_plant_line_capacity', 'cm_p21_fuel_260914', null, '燃料化設備：脱水・油回収', '燃料化設備1系列で処理できる菌体の量', 50000000, null, 'kg-DCW/年', 'H', '仮置き', 'AMD（内部）', true, 'plant_line_capacity_kg_year', '脱水・細胞破砕・溶媒抽出・溶媒回収（自社で行うときはFAME転換も）の設備1系列で、年に処理できる乾燥菌体の量。1日あたり約167t（稼働300日）の中規模の化学プラントとして置いた。年に要る菌体の量 ÷ この量 の数だけ系列を並べる。量産で設備を大きくしたときの規模の経済は入れていない。', 'amd_internal', 210, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_labor_rate', 'cm_p21_fuel_260914', null, '人件費（作業）', '作業単価（共通）', 4000, null, '円/時', 'B', '仮置き', 'AMD', false, 'labor_rate', 'すべての作業に共通の作業単価（排水処理のコスト試算と同じ4,000円/時）。作業の年額 ＝ 年間回数 ×（1回の工数 × この単価 ＋ 1回の経費）。', 'amd_internal', 300, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_residue_route', 'cm_p21_fuel_260914', null, '残渣の処理', '残渣の行き先', null, 'digestion', null, 'H', '仮置き', 'AMD（内部）', true, 'residue_route', '油を取ったあとの残渣（菌体の大部分）をどう処理するか。「発酵などで処理」はメタン発酵などで処理し、処理費とガス・液肥の価値が相殺される前提。「産業廃棄物として処分」は、脱水した残渣を汚泥として処分業者に出す前提で、残渣の乾燥1kgあたり 湿重量倍率 × 処分単価 がかかる。行き先はまだ決めていない。', 'amd_internal', 400, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_residue_dry', 'cm_p21_fuel_260914', null, '残渣の処理', '残渣の量（乾燥）', 0.878, null, 'kg/kg-DCW', 'B', '資料記載', 'AMD（内部）', false, 'residue_dry_kg_per_kg_dcw', '2026-09-07 の工程とマテバラ推定の基準ケースで、乾燥菌体1tから出る菌体・有機残渣（乾燥換算）878.10kg。タンパク質・糖・取り出せなかった脂質・灰分など。収率を変えても、この量は変えていない。', 'amd_internal', 401, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_residue_digestion_cost', 'cm_p21_fuel_260914', null, '残渣の処理', '発酵などで処理するときの正味の費用', 0, null, '円/kg-乾燥残渣', 'H', '仮置き', 'AMD（内部）', false, 'residue_digestion_cost', 'メタン発酵でガスと液肥にし、処理費とガス・液肥の価値が相殺される前提で0円と置いた（未確認）。メタン発酵の液肥の肥料成分の価値は約2,800円/tという評価がある（農林水産省関連資料）。残渣からフィコシアニンなどの有価物を取る場合の売上は入れていない。', 'amd_internal', 402, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_residue_wet_factor', 'cm_p21_fuel_260914', null, '残渣の処理', '脱水後の湿重量倍率', 5, null, 'kg湿/kg-乾燥残渣', 'H', '推定', '中島先生', false, 'residue_wet_factor', '含水率80%まで脱水して出す想定（乾燥1kg → 湿重量5kg）。排水処理のコスト試算の使用済み菌体と同じ置き方。産業廃棄物として処分するときだけ効く。', 'amd_internal', 403, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_residue_disposal_price', 'cm_p21_fuel_260914', null, '残渣の処理', '汚泥の処分単価（収集運搬込み）', 35, null, '円/kg湿', 'B', '資料記載', '処分業者（見積）', false, 'residue_disposal_price', '産業廃棄物（汚泥）の処理料金相場 25〜50円/kg の中央（排水処理のコスト試算と同じ値）。産業廃棄物として処分するときだけ効く。', 'amd_internal', 404, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_truck_capacity', 'cm_p21_fuel_260914', null, '品質確認・出荷', '出荷1台の積載量（タンクローリー）', 20000, null, 'L/台', 'B', '資料記載', '運送会社（見積）', false, 'truck_capacity_l', '大型のタンクローリー（12〜20kL級）の上限で置いた。セミトレーラーなら20〜30kL（消防法の上限30kL）。作業「タンクローリーでの出荷」の回数は、年間の燃料の量 ÷ この値で決まる。', 'amd_internal', 500, null, null);
insert into project_cost_assumptions (cost_assumption_id, cost_model_id, code, group_label, label, value, value_text, unit, confidence, source_kind, owner, is_key, role_key, note, visibility, sort_order, strain, application) values ('caf_lot_size', 'cm_p21_fuel_260914', null, '品質確認・出荷', '品質確認1ロットの量', 500000, null, 'L/ロット', 'H', '仮置き', '販売先（品質契約）', false, 'lot_size_l', '出荷前に規格（JIS K2390 相当）の分析を1回行う量。貯槽1基分（500kL）で置いた。販売先との品質契約で決まる。作業「品質の分析」の回数は、年間の燃料の量 ÷ この値で決まる。', 'amd_internal', 501, null, null);
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_culture_043', 'cm_p21_fuel_260914', '中央培養', 'CAPEX', '培養設備', '培養槽本体', '槽・架台', '初期投資配賦', 1, '基', 1200000, '円/基', null, 1, 7, false, 'C', '推測', 'AMD', '排水処理のコスト試算（260914版）の培養設備1系列からコピーした行。 菌体の製造拠点の構成は「円盤型培養設備／培養液供給設備／菌体濃縮設備／菌体保管・輸送設備」。
