insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_culture_057', 'cm_p21_fuel_260914', '中央培養', 'CAPEX', '培養設備', '菌体濃縮設備', '濃縮', '初期投資配賦', 1, '式', 2500000, '円/式', null, 1, 7, false, 'H', '予測', 'AMD', '排水処理のコスト試算（260914版）の培養設備1系列からコピーした行。 菌体の製造拠点で培養液から菌体を分離・濃縮する設備。現行の培養槽まわり14項目には含まれていなかったため新規計上。金額は予測値（連続式遠心分離機または膜濃縮ユニット小型機を想定）。実機選定・見積で要更新。', 'amd_internal', 1014, null, null, 'sx');
