insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_culture_128', 'cm_p21_fuel_260914', '中央培養', 'OPEX', '培養', '濃縮・回収', '濃縮補助材', '毎kg菌体比例', 1, 'kg-DCW', 5.4, '円/kg-DCW', null, 1, null, false, 'C', '仮置き', 'AMD', '排水処理のコスト試算（260914版）の培養設備1系列からコピーした行。 二段階版で 円/m³ → 円/kg-DCW へ換算した（旧版の基準菌体量 1.111 kg-DCW/m³ で割った値）。', 'amd_internal', 1026, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_culture_129', 'cm_p21_fuel_260914', '中央培養', 'OPEX', '培養', '品質確認', 'サンプリング分析', '年額固定', 1, '年', 120000, '円/年', null, 1, null, false, 'C', '仮置き', 'AMD', '排水処理のコスト試算（260914版）の培養設備1系列からコピーした行。 二段階版で年額固定に換算した（旧版の4円/m³ × 30,000m³）。検査の回数は菌体量ではなくバッチに付くため。 2026-09-14 から、培養設備1系列あたりの年額として、系列の数だけ増やす。', 'amd_internal', 1027, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_culture_130', 'cm_p21_fuel_260914', '中央培養', 'OPEX', '培養', '品質確認', '品質確認試験', '年額固定', 1, '年', 120000, '円/年', null, 1, null, false, 'C', '仮置き', 'AMD', '排水処理のコスト試算（260914版）の培養設備1系列からコピーした行。 二段階版で年額固定に換算した（旧版の4円/m³ × 30,000m³）。検査の回数は菌体量ではなくバッチに付くため。 2026-09-14 から、培養設備1系列あたりの年額として、系列の数だけ増やす。', 'amd_internal', 1028, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_culture_134', 'cm_p21_fuel_260914', '中央培養', 'OPEX', '培養', 'ロス補充', '培養ロス補充', '毎kg菌体比例', 1, 'kg-DCW', 5.4, '円/kg-DCW', null, 1, null, false, 'C', '仮置き', 'AMD', '排水処理のコスト試算（260914版）の培養設備1系列からコピーした行。 二段階版で 円/m³ → 円/kg-DCW へ換算した（旧版の基準菌体量 1.111 kg-DCW/m³ で割った値）。', 'amd_internal', 1029, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_plant_dewater', 'cm_p21_fuel_260914', '共通', 'CAPEX', '脱水・油回収', '脱水設備', 'デカンター型遠心分離機など', '初期投資配賦', 1, '式', 300000000, '円/式', null, 1, 15, false, 'H', '推測', 'プラントメーカー（見積）', '濃縮した菌体を固形分20%まで脱水する。燃料化設備1系列（乾燥菌体 年5万t）あたり。見積はない。従来型のバイオディーゼル工場の初期投資（年産能力1tあたり約300〜450ドル）や、大豆の溶媒抽出工場を手がかりに、湿った菌体の細胞破砕と乳化対策の分を上乗せした目安。プラントメーカーの概算で置き換える。', 'amd_internal', 2000, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_plant_disruption', 'cm_p21_fuel_260914', '共通', 'CAPEX', '脱水・油回収', '細胞破砕設備', '高圧ホモジナイザーなど', '初期投資配賦', 1, '式', 400000000, '円/式', null, 1, 15, false, 'H', '推測', 'プラントメーカー（見積）', '湿った菌体の細胞を壊し、膜の脂質を溶媒に移しやすくする。燃料化設備1系列（乾燥菌体 年5万t）あたり。見積はない。従来型のバイオディーゼル工場の初期投資（年産能力1tあたり約300〜450ドル）や、大豆の溶媒抽出工場を手がかりに、湿った菌体の細胞破砕と乳化対策の分を上乗せした目安。プラントメーカーの概算で置き換える。', 'amd_internal', 2001, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_plant_extraction', 'cm_p21_fuel_260914', '共通', 'CAPEX', '脱水・油回収', '溶媒抽出・相分離設備', '混合槽・分離機', '初期投資配賦', 1, '式', 800000000, '円/式', null, 1, 15, false, 'H', '推測', 'プラントメーカー（見積）', '極性と非極性の溶媒で脂質を取り出し、水・残渣と分ける。溶媒の組成は未決。燃料化設備1系列（乾燥菌体 年5万t）あたり。見積はない。従来型のバイオディーゼル工場の初期投資（年産能力1tあたり約300〜450ドル）や、大豆の溶媒抽出工場を手がかりに、湿った菌体の細胞破砕と乳化対策の分を上乗せした目安。プラントメーカーの概算で置き換える。', 'amd_internal', 2002, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_plant_solvent_recovery', 'cm_p21_fuel_260914', '共通', 'CAPEX', '脱水・油回収', '溶媒回収設備', '蒸留塔・凝縮器', '初期投資配賦', 1, '式', 700000000, '円/式', null, 1, 15, false, 'H', '推測', 'プラントメーカー（見積）', '循環させる溶媒（菌体1kgあたり3kg）を蒸留で回収して使い回す。燃料化設備1系列（乾燥菌体 年5万t）あたり。見積はない。従来型のバイオディーゼル工場の初期投資（年産能力1tあたり約300〜450ドル）や、大豆の溶媒抽出工場を手がかりに、湿った菌体の細胞破砕と乳化対策の分を上乗せした目安。プラントメーカーの概算で置き換える。', 'amd_internal', 2003, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_plant_residue', 'cm_p21_fuel_260914', '共通', 'CAPEX', '残渣を処理する', '残渣の脱水・搬出設備', '脱水機・コンベア・保管', '初期投資配賦', 1, '式', 300000000, '円/式', null, 1, 15, false, 'H', '推測', 'プラントメーカー（見積）', '油を取ったあとの残渣を脱水し、搬出するまで保管する。燃料化設備1系列（乾燥菌体 年5万t）あたり。見積はない。従来型のバイオディーゼル工場の初期投資（年産能力1tあたり約300〜450ドル）や、大豆の溶媒抽出工場を手がかりに、湿った菌体の細胞破砕と乳化対策の分を上乗せした目安。プラントメーカーの概算で置き換える。', 'amd_internal', 2004, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_plant_utility', 'cm_p21_fuel_260914', '共通', 'CAPEX', '脱水・油回収', '付帯設備・据付工事', '配管・計装・電気・土木・排水処理', '初期投資配賦', 1, '式', 1500000000, '円/式', null, 1, 15, false, 'H', '推測', 'プラントメーカー（見積）', '機器の据付と、配管・計装・受変電・建屋・工場の排水処理。化学プラントでは機器代の数倍になることが多い。燃料化設備1系列（乾燥菌体 年5万t）あたり。見積はない。従来型のバイオディーゼル工場の初期投資（年産能力1tあたり約300〜450ドル）や、大豆の溶媒抽出工場を手がかりに、湿った菌体の細胞破砕と乳化対策の分を上乗せした目安。プラントメーカーの概算で置き換える。', 'amd_internal', 2005, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_ship_tank', 'cm_p21_fuel_260914', '共通', 'CAPEX', '品質を確かめて出荷する', '製品の貯槽・出荷設備', 'FAMEの貯槽・ローリーの積み込み', '初期投資配賦', 1, '式', 150000000, '円/式', null, 1, 15, false, 'H', '推測', 'プラントメーカー（見積）', '精製したFAMEをためて、タンクローリーに積み込む設備。燃料化設備1系列あたり。見積はない。', 'amd_internal', 2006, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_op_power', 'cm_p21_fuel_260914', '共通', 'OPEX', '脱水・油回収', '電力', '脱水・細胞破砕・抽出・ポンプ', '毎kg菌体比例', 0.3, 'kWh/kg-DCW', 17.45, '円/kWh', null, 1, null, false, 'H', '推定', 'プラントメーカー（見積）', '乾燥菌体1kgあたり0.3kWhは見積のない目安（細胞破砕が大部分）。単価は特別高圧の産業用電力の全国平均 17.45円/kWh（2026年5月、新電力ネット）。排水処理のコスト試算の電力単価（27円/kWh）は高圧の小口を想定した値で、燃料化設備の規模は特別高圧になるため分けた。', 'amd_internal', 2100, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_op_heat', 'cm_p21_fuel_260914', '共通', 'OPEX', '脱水・油回収', '熱', '溶媒の蒸留回収', '毎kg菌体比例', 1.5, 'MJ/kg-DCW', 2.3, '円/MJ', null, 1, null, false, 'H', '推定', 'プラントメーカー（見積）', '循環させる溶媒（菌体1kgあたり3kg）を蒸留で回収する熱を、乾燥菌体1kgあたり1.5MJと置いた（熱の回収を含む目安、見積なし）。単価は蒸気1tあたり約5,000円（仮置き）。溶媒の種類で変わる。', 'amd_internal', 2101, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_op_solvent', 'cm_p21_fuel_260914', '共通', 'OPEX', '脱水・油回収', '抽出溶媒の補給', '回収できない分', '毎kg菌体比例', 0.0285, 'kg/kg-DCW', 200, '円/kg', null, 1, null, false, 'H', '仮置き', '溶媒メーカー（見積）', '量は2026-09-07 の工程とマテバラ推定（循環する溶媒 2,850kg のうち99%を回収し、乾燥菌体1tあたり28.5kgを補給）。単価は溶媒の種類が未決のため1kgあたり200円の仮置き。', 'amd_internal', 2102, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_op_water', 'cm_p21_fuel_260914', '共通', 'OPEX', '脱水・油回収', '水', '抽出・洗浄の水', '毎kg菌体比例', 0.0002, 'm³/kg-DCW', 200, '円/m³', null, 1, null, false, 'C', '仮置き', 'AMD（内部）', '量は2026-09-07 の工程とマテバラ推定（乾燥菌体1tあたり0.2m³）。単価は工業用水の目安。', 'amd_internal', 2103, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_op_maintenance', 'cm_p21_fuel_260914', '共通', 'OPEX', '脱水・油回収', '設備の保守', '燃料化設備（脱水・油回収・残渣・出荷）の初期投資の3%/年', '年額固定', 1, '年', 124500000, '円/年', null, 1, null, false, 'H', '仮置き', 'プラントメーカー（見積）', '燃料化設備1系列の初期投資（41.5億円）の3%/年。初期投資の明細を書き換えたら、この額も合わせて直す。', 'amd_internal', 2104, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_out_tolling', 'cm_p21_fuel_260914', '外部委託', 'OPEX', 'FAMEにする', 'FAME転換・精製の委託費', '委託先で酸触媒の前処理・反応・精製', '毎m³比例', 1, 'L', 60, '円/L', null, 1, null, false, 'H', '仮置き', '精製事業者（見積）', '見積はない。国内の廃食用油から作るBDFの製造原価は平均259.5円/L（2021年度、全国油脂事業協同組合連合会の実態調査。原料の回収を含む小規模設備）。藻類の原料油は遊離脂肪酸・リン脂質・色素・金属が多く、酸触媒の前処理が要る。精製事業者の見積で置き換える。', 'amd_internal', 3000, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_out_transport', 'cm_p21_fuel_260914', '外部委託', 'OPEX', 'FAMEにする', '委託先までの原料油の輸送', 'タンクローリー', '毎m³比例', 1, 'L', 5, '円/L', null, 1, null, false, 'H', '仮置き', '運送会社（見積）', '20kL級のタンクローリーで片道100km程度を1回約10万円と置いた目安（見積なし）。', 'amd_internal', 3001, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_in_capex', 'cm_p21_fuel_260914', '自社精製', 'CAPEX', 'FAMEにする', 'FAME転換・精製設備', '前処理・反応槽・メタノール回収・洗浄・吸着・乾燥', '初期投資配賦', 1, '式', 500000000, '円/式', null, 1, 15, false, 'H', '推測', 'プラントメーカー（見積）', '燃料化設備1系列あたり。従来型のバイオディーゼル工場の初期投資（年産能力1tあたり約300〜450ドル）を、改善ケースの生産量（1系列 年約9,100t）に当てはめ、藻類の原料油の前処理を上乗せした目安（見積なし）。', 'amd_internal', 3100, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_in_methanol', 'cm_p21_fuel_260914', '自社精製', 'OPEX', 'FAMEにする', 'メタノール', '反応で使う分と回収できない分', '毎m³比例', 0.1278, 'kg/L', 50, '円/kg', null, 1, null, false, 'C', '推定', '化学品商社（見積）', '量は2026-09-07 の工程とマテバラ推定（乾燥菌体1tあたり11.80kg ÷ 精製FAME 92.36L）。単価はアジアのスポット価格 約318ドル/t（2025年第3四半期、名古屋着）からの目安。', 'amd_internal', 3101, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_in_acid', 'cm_p21_fuel_260914', '自社精製', 'OPEX', 'FAMEにする', '硫酸（触媒）', '純分換算', '毎m³比例', 0.01234, 'kg/L', 30, '円/kg', null, 1, null, false, 'H', '仮置き', '化学品商社（見積）', '量は2026-09-07 の工程とマテバラ推定（抽出した脂質の1%、乾燥菌体1tあたり1.14kg）。単価は仮置き。', 'amd_internal', 3102, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_in_naoh', 'cm_p21_fuel_260914', '自社精製', 'OPEX', 'FAMEにする', '苛性ソーダ（中和）', '純分換算', '毎m³比例', 0.01007, 'kg/L', 60, '円/kg', null, 1, null, false, 'H', '推定', '化学品商社（見積）', '量は2026-09-07 の工程とマテバラ推定（乾燥菌体1tあたり0.93kg）。単価は液体の貿易統計の単価 約28円/kg（2023年）に、2026年の値上げ（固形換算30円/kg以上）を足した目安。', 'amd_internal', 3103, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_in_adsorbent', 'cm_p21_fuel_260914', '自社精製', 'OPEX', 'FAMEにする', '吸着剤', '粗FAMEの1%', '毎m³比例', 0.00899, 'kg/L', 100, '円/kg', null, 1, null, false, 'H', '仮置き', '化学品商社（見積）', '量は2026-09-07 の工程とマテバラ推定（粗FAMEの1%）。単価は仮置き。', 'amd_internal', 3104, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_in_utilities', 'cm_p21_fuel_260914', '自社精製', 'OPEX', 'FAMEにする', '電力・熱', 'メタノールの回収・乾燥', '毎m³比例', 1, 'L', 3, '円/L', null, 1, null, false, 'H', '仮置き', 'プラントメーカー（見積）', 'マテバラ推定はエネルギーを計算していない。メタノールの蒸留回収と製品の乾燥の目安（見積なし）。', 'amd_internal', 3105, null, null, 'sx');
insert into project_cost_items (cost_item_id, cost_model_id, scenario, cost_type, group_label, mid_label, leaf_label, basis, quantity, quantity_unit, unit_price, unit_price_unit, price_rule, annual_factor, useful_life_years, is_breakdown, confidence, source_kind, owner, note, visibility, sort_order, strain, application, bearer) values ('cif_in_maintenance', 'cm_p21_fuel_260914', '自社精製', 'OPEX', 'FAMEにする', 'FAME転換設備の保守', '初期投資の3%/年', '年額固定', 1, '年', 15000000, '円/年', null, 1, null, false, 'H', '仮置き', 'プラントメーカー（見積）', 'FAME転換・精製設備（5億円）の3%/年。初期投資を書き換えたら、この額も合わせて直す。', 'amd_internal', 3106, null, null, 'sx');
insert into project_cost_tasks (cost_task_id, cost_model_id, scenario, strain, application, group_label, label, hours_per_occurrence, count_driver, count_per_year, hourly_rate, expense_per_occurrence, confidence, source_kind, owner, note, visibility, sort_order, performer) values ('ctf_culture_operation', 'cm_p21_fuel_260914', '中央培養', null, null, '菌体をつくる', '培養・濃縮の運転（1日分）', null, 'production_line', 300, null, 0, 'H', '仮置き', '杉浦先生・中島先生', '排水処理のコスト試算（260914版）の培養設備1系列からコピーした行。毎日の培養の管理と、菌体を濃縮して燃料化設備へ送れる状態にする作業。1日あたりの工数が分かっていないので空欄（未確認）で、0時間として数えている。1系列あたり年300日 × 系列数。', 'amd_internal', 10, 'sx');
insert into project_cost_tasks (cost_task_id, cost_model_id, scenario, strain, application, group_label, label, hours_per_occurrence, count_driver, count_per_year, hourly_rate, expense_per_occurrence, confidence, source_kind, owner, note, visibility, sort_order, performer) values ('ctf_plant_operation', 'cm_p21_fuel_260914', '共通', null, null, '脱水・油回収', '脱水と油回収の運転（1日分）', 72, 'plant_line', 300, null, 0, 'H', '仮置き', 'プラントメーカー（見積）', '脱水・細胞破砕・溶媒抽出・溶媒回収・残渣の搬出を、24時間の3交代・1直3人で運転する目安（1日72時間）。燃料化設備1系列あたり年300日 × 系列数。', 'amd_internal', 20, 'sx');
insert into project_cost_tasks (cost_task_id, cost_model_id, scenario, strain, application, group_label, label, hours_per_occurrence, count_driver, count_per_year, hourly_rate, expense_per_occurrence, confidence, source_kind, owner, note, visibility, sort_order, performer) values ('ctf_inhouse_operation', 'cm_p21_fuel_260914', '自社精製', null, null, 'FAMEにする', 'FAME転換と精製の運転（1日分）', 24, 'plant_line', 300, null, 0, 'H', '仮置き', 'プラントメーカー（見積）', 'FAME転換と精製を、24時間の3交代・1直1人で運転する目安（1日24時間）。自社で行うときだけ。燃料化設備1系列あたり年300日 × 系列数。', 'amd_internal', 30, 'sx');
insert into project_cost_tasks (cost_task_id, cost_model_id, scenario, strain, application, group_label, label, hours_per_occurrence, count_driver, count_per_year, hourly_rate, expense_per_occurrence, confidence, source_kind, owner, note, visibility, sort_order, performer) values ('ctf_ship_qc', 'cm_p21_fuel_260914', '共通', null, null, '品質を確かめて出荷する', '品質の分析（1ロット）', 2, 'batch', null, null, 150000, 'H', '仮置き', '分析機関（見積）', '出荷前にJIS K2390 相当の項目を外部の分析機関で測る目安（1回15万円、見積なし）と、試料の採取・記録の2時間。回数は 年間の燃料の量 ÷ 品質確認1ロットの量。', 'amd_internal', 40, 'sx');
insert into project_cost_tasks (cost_task_id, cost_model_id, scenario, strain, application, group_label, label, hours_per_occurrence, count_driver, count_per_year, hourly_rate, expense_per_occurrence, confidence, source_kind, owner, note, visibility, sort_order, performer) values ('ctf_ship_truck', 'cm_p21_fuel_260914', '共通', null, null, '品質を確かめて出荷する', 'タンクローリーでの出荷（1台）', 0, 'truck_trip', null, null, 60000, 'H', '仮置き', '運送会社（見積）', '運送会社に頼む前提で、工数を0にして運賃を1回の経費に置いた（20kL級・片道100km程度で1回6万円、見積なし）。回数は 年間の燃料の量 ÷ 出荷1台の積載量。', 'amd_internal', 41, 'sx');
insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cnf_caveat_yield', 'cm_p21_fuel_260914', 'caveat', '収率はSX株の実測ではない', '燃料1Lに要る菌体の量は、全菌体のFAMEポテンシャル × 菌体回収率 × 脂質抽出回収率 × メチル化反応率 × FAME精製回収率 で決まる。どれも2026-09-07 の工程とマテバラ推定の設計仮定で、SX株では測っていない。
insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cnf_caveat_biomass', 'cm_p21_fuel_260914', 'caveat', '総コストの大半は菌体費で、培養設備は排水処理の試算のコピー', '燃料1Lには、基準の収率で乾燥菌体が約10.8kg要る（改善で約4.8kg、低位で約27kg）。菌体1kgの原価がそのまま約10.8倍（改善で約4.8倍）になって燃料1Lに乗る。
insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cnf_caveat_plant', 'cm_p21_fuel_260914', 'caveat', '燃料化設備・電力・熱・委託費は見積のない仮置き', '脱水・細胞破砕・溶媒抽出・溶媒回収の設備、FAME転換の設備、電力と熱の量と単価、溶媒の単価、委託費、運賃、分析費は、どれも見積がない。公開資料の目安（従来型のバイオディーゼル工場の初期投資、国内の電力単価、汚泥の処分相場など）から置いた（確度はH）。
insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cnf_caveat_residue', 'cm_p21_fuel_260914', 'caveat', '残渣の行き先で総コストの桁が変わる', '油を取ったあとの残渣は、乾燥菌体1kgあたり約0.88kg（乾燥）で、菌体の大部分が残る。いまは発酵などで処理し、処理費とガス・液肥の価値が相殺される前提（0円）で置いている。
insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cnf_caveat_line', 'cm_p21_fuel_260914', 'caveat', '排水処理とは別のラインで、金属回収に使った菌体は原料にしない', '燃料のために培養した菌体だけを原料にする（事業概要 2026-09-03「金属を含む排水処理ラインと燃料生産ラインは分離し、安全性と品質を守る」）。
insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cnf_bench_price', 'cm_p21_fuel_260914', 'benchmark', '売価と原価の目安', '| 項目 | 値 | 出典 |
insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cnf_bench_plant', 'cm_p21_fuel_260914', 'benchmark', '設備と単価の目安', '| 項目 | 値 | 出典 |
insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cnf_guide', 'cm_p21_fuel_260914', 'reading_guide', 'この画面の見方', '- 上の切り替えで、FAME転換（外部に委託 / 自社で行う）と収率（低位 / 基準 / 改善）を選ぶ。右の結果の欄には6通りの総コストを同じ目盛りの棒で並べる。破線が売価、点線が原価目標
insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cnf_history_v1', 'cm_p21_fuel_260914', 'history', '260914版（初版）', '2026-09-14 まさ「OSの技術ページに、新たに『コスト試算（燃料）』を追加してほしい。廃液処理のコスト試算と同様にバイオディーゼル事業のコスト試算シートを作ってほしい」で作った。
insert into project_cost_notes (cost_note_id, cost_model_id, section, title, body_md, source_url, source_label, visibility, sort_order) values ('cnf_history_gaps', 'cm_p21_fuel_260914', 'history', 'この試算が答えていないこと', '- SAF（航空燃料）まで加工する場合（水素化精製の委託費と歩留まり）
insert into project_cost_questions (cost_question_id, cost_model_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cqf_fame_potential', 'cm_p21_fuel_260914', '外部の分析機関（杉浦先生のサンプル）', 'SXの自然株の乾燥菌体で、①全菌体のFAMEポテンシャル（全菌体をそのままメチル化して測る方法） ②脂肪酸の組成 ③灰分 を測ってください。同じ培養サンプルで乾燥重量も測ります。', '燃料1Lに要る菌体の量は、FAMEポテンシャルに反比例する。基準の10%が5%なら菌体費と菌体に比例する費用は2倍、20%なら半分。いまは設計仮定で、SX株では測っていない。杉浦先生に聞いても分からないため、乾燥菌体を外部の分析に出す方針（2026-09-10）。', 629, 1258, 'open', null, null, 'caf_fame_potential', 'amd_internal', 10);
insert into project_cost_questions (cost_question_id, cost_model_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cqf_culture', 'cm_p21_fuel_260914', '杉浦先生', '燃料向けの培養の物量を教えてください。①培養液1Lあたり1日で何g（乾燥重量）増えますか ②窒素やリンを減らしたとき、油（脂質）の割合と増え方はどう変わりますか ③何日ごとに収穫しますか ④まだ分からない場合、それを確かめる実験の条件と回数は。', '培養設備1系列で年に作れる菌体の量が決まり、菌体1kgの原価に効く。燃料の総コストは菌体費が大半を占める。円ではなく量と条件を聞いて、AMD側で円に変える。', 172, 344, 'open', null, null, 'caf_culture_line_capacity', 'amd_internal', 20);
insert into project_cost_questions (cost_question_id, cost_model_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cqf_extraction', 'cm_p21_fuel_260914', '中島先生', '固形分20%程度の湿った菌体から溶媒で油を取り出すとき、①どの溶媒と装置を想定しますか ②油はどのくらいの割合で取り出せますか ③溶媒はどのくらい回収して使い回せますか ④乳化で分けにくくなりますか。', '脂質抽出回収率（基準90%）と、溶媒の補給・蒸留の熱に効く。', 66, 157, 'open', null, null, 'caf_extraction_recovery', 'amd_internal', 30);
insert into project_cost_questions (cost_question_id, cost_model_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cqf_tolling', 'cm_p21_fuel_260914', '精製事業者（バイオディーゼル工場）', '藻類から取った原料油のFAME転換・精製を受託できますか。①委託費（円/L） ②受け入れる原料油の条件（遊離脂肪酸・リン・金属・水分） ③最低の量と頻度 ④FAMEになる割合。', 'FAME転換を委託するときの費用（いまは委託費60円/L・輸送5円/Lの仮置き）と、メチル化・精製の歩留まりに効く。', 30, 60, 'open', null, null, null, 'amd_internal', 40);
insert into project_cost_questions (cost_question_id, cost_model_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cqf_offtake', 'cm_p21_fuel_260914', '船舶燃料の販売先・商社', '船舶向けのFAME（またはFAMEを混ぜた燃料）の引き取り条件を教えてください。①価格（円/L） ②引き渡し場所と物流 ③品質の規格 ④年に必要な量。', '想定売価200円/Lは米国の小売の参照値（約183円/L）から置いた仮置き。売価が変わると、売価で成立する菌体の原価がそのまま動く。', null, null, 'open', null, null, 'caf_sale_price', 'amd_internal', 50);
insert into project_cost_questions (cost_question_id, cost_model_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cqf_residue', 'cm_p21_fuel_260914', 'AMD内部', '油を取ったあとの残渣（菌体の約9割）をどうしますか。①メタン発酵して熱と液肥にする ②フィコシアニンなどの有価物を先に取る ③産業廃棄物として処分する。', '産業廃棄物として処分すると、燃料1Lあたりの総コストが大きく上がる（前提「残渣の行き先」で見られる）。有価物を取るなら、燃料より残渣の売上が主になる可能性がある（2026-09-10 の整理）。', 0, 1664, 'open', null, null, 'caf_residue_route', 'amd_internal', 60);
insert into project_cost_questions (cost_question_id, cost_model_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cqf_plant', 'cm_p21_fuel_260914', 'プラントメーカー（中島先生経由）', '乾燥菌体で年5万t（1日約170t）を処理する燃料化設備（脱水・細胞破砕・溶媒抽出・溶媒回収・残渣の脱水）の、①概算の初期投資 ②電力と熱の使用量 ③運転の人数 を教えてください。', '燃料化設備の償却と保守、電力・熱、運転の作業（いまはどれも見積のない仮置き）に効く。', 90, 181, 'open', null, null, 'caf_plant_line_capacity', 'amd_internal', 70);
insert into project_cost_questions (cost_question_id, cost_model_id, addressee, question, why_it_matters, impact_low, impact_high, status, answer, answered_on, linked_assumption_id, visibility, sort_order) values ('cqf_culture_unit', 'cm_p21_fuel_260914', '杉浦先生・中島先生', '燃料の量産で使う培養設備は、1系列で年に何tの菌体を作る大きさを想定しますか。品質の確認は系列ごとに必要ですか、拠点ごとでよいですか。', 'いまの1系列（年33,333kg）のままだと系列が1万を超え、系列ごとの品質確認（年24万円）がそのまま積み上がる。', 0, 78, 'open', null, null, 'caf_culture_line_capacity', 'amd_internal', 80);
